export interface FileExample {
    id: string;
    /** Menu label. */
    label: string;
    /** Tooltip / menu description. */
    description: string;
    language: ExampleLanguage;
    /** Category WITHIN the language (e.g. Plotting, Statistics). Drives
     *  the nested submenu structure in the Examples menu and the
     *  Explorer's "New example…" submenu. */
    category: string;
    /** Subcategory WITHIN the category — keeps 20+ entry
     *  categories scannable by splitting them into small labeled
     *  groups inside each category submenu. */
    subcategory: string;
    /** Canonical snake_case base name (styled at creation time). */
    baseName: string;
    /** File extension including the dot ("" for dotfiles). */
    extension: string;
    /** LITERAL file name for canonical files whose name
     *  must NOT be naming-styled — pyproject.toml, requirements.txt,
     *  .editorconfig, Makefile, Dockerfile, LICENSE, __init__.py,
     *  conftest.py… (a styled "Pyproject.toml" or "EditorConfig.editorconfig"
     *  would be useless). When set, `baseName`/`extension` are only used
     *  for menu bookkeeping. */
    fixedName?: string;
    /** Renders the file body in the naming style. */
    build: (styles: NamingStyleSettings) => string;
}

