/** Render the styled file name for an example (with a numeric suffix
 * on collision — handled by the creator, which appends " 2" etc.).
 * examples with a `fixedName` (pyproject.toml,
 *.editorconfig, Makefile, __init__.py, …) keep their canonical,
 * non-styled name — a styled "Pyproject.toml" would be useless. */
export function exampleFileName(
    ex: FileExample,
    styles: NamingStyleSettings
): string {
    if (ex.fixedName) return ex.fixedName;
    const styled = applyNamingStyle(styles.files, ex.baseName);
    return `${styled}${ex.extension}`;
}

