/** One subcategory bucket inside a category. */
export interface ExampleSubcategory {
    label: string;
    examples: FileExample[];
}

/** One category bucket inside a language group. `examples` is the
 *  flat list (for counting/badges); `subcategories` nests the same
 *  entries under their subcategory labels. */
export interface ExampleCategory {
    label: string;
    subcategories: ExampleSubcategory[];
    examples: FileExample[];
}

/** A language group: label + its category buckets. */
export interface ExampleGroup {
    label: string;
    categories: ExampleCategory[];
}

/** normalize menu labels to Capital Case. The library
 *  mixes styles — older modules use sentence case ("Correlation &
 *  regression"), others all-lowercase ("asyncio basics"),
 *  Other a third mix. Every CATEGORY and SUBCATEGORY label now passes
 *  through here so the menus read uniformly: "Correlation & Regression",
 *  "Asyncio Basics". Rules: capitalize the first letter of every word
 *  (space- or hyphen-separated); leave symbols (& / +), digits and
 *  already-uppercase words (CSV, CI, 3D) alone. Applied at this choke
 *  point — categorize — so the menu bar, the explorer's "New
 *  example…" submenu and every consumer of exampleGroups/menu nodes
 *  get the same labels with zero data-file churn (labels are display-
 *  only; example ids / file names are untouched). */
function toCapitalCase(label: string): string {
    if (!label) return label;
    const isUpperish = (w: string) =>
        w.length > 0 && w === w.toUpperCase() && /[A-Z0-9]/.test(w);
    // Pascal Case for every word — the menus and submenus of the
    // Examples library read as "Asyncio Basics", "Csv Join" (each word
    // capitalized; ALL-CAPS acronyms like CSV stay verbatim).
    const cap = (w: string): string => {
        if (!w || isUpperish(w)) return w; // CSV, CI, 3D, "", "&"…
        return w.charAt(0).toUpperCase() + w.slice(1).toLowerCase();
    };
    return label
        .trim()
        .split(/(\s+)/) // keep the separators
        .map((tok) => (/^\s+$/.test(tok) ? tok : tok.split("-").map(cap).join("-")))
        .join("");
}

/** Group examples by category, then by subcategory — preserving each
 * level's first-appearance order. labels pass through
 *  toCapitalCase so every menu reads Capital Case. */
function categorize(examples: FileExample[]): ExampleCategory[] {
    const cats: ExampleCategory[] = [];
    const byLabel = new Map<string, ExampleCategory>();
    for (const ex of examples) {
        let bucket = byLabel.get(ex.category);
        if (!bucket) {
            bucket = {label: toCapitalCase(ex.category), subcategories: [], examples: []};
            byLabel.set(ex.category, bucket);
            cats.push(bucket);
        }
        bucket.examples.push(ex);
        const normalizedSub = toCapitalCase(ex.subcategory);
        let sub = bucket.subcategories.find((s) => s.label === normalizedSub);
        if (!sub) {
            sub = {label: normalizedSub, examples: []};
            bucket.subcategories.push(sub);
        }
        sub.examples.push(ex);
    }
    return cats;
}

/** — normalized menu node for one level under a language. */
export interface ExampleMenuNode {
    /** Menu label (a category name, or a subcategory name for
     *  single-category language groups). */
    label: string;
    /** Total examples under this node. */
    count: number;
    /** Category node: its subcategory children. */
    subcategories?: ExampleSubcategory[];
    /** Subcategory node (single-category groups): the examples render
     *  DIRECTLY under this node, skipping the redundant category level. */
    examples?: FileExample[];
}

/** menu nodes for one language group. Groups with a SINGLE
 *  category (R, SQL, JSON, YAML, Shell — the additions) skip
 *  the redundant category level, so the language submenu lists its
 *  subcategories directly — "like yaml, u can grap the last examples
 *  into sub cats". Multi-category groups (Python, Markdown, Text,
 *  Other) keep language → category → subcategory → item. */
export function exampleMenuNodes(group: ExampleGroup): ExampleMenuNode[] {
    if (group.categories.length === 1) {
        return group.categories[0].subcategories.map((s) => ({
            label: s.label,
            count: s.examples.length,
            examples: s.examples,
        }));
    }
    return group.categories.map((c) => ({
        label: c.label,
        count: c.examples.length,
        subcategories: c.subcategories,
    }));
}

/** Grouped listing for menus: language → category → subcategory →
 * examples. nine language groups — Python (1,000 entries),
 * Markdown / Text / Other (50 per category), plus the five new groups
 * R, SQL, JSON, YAML and Shell (50 entries each).
 * the catch-all "Other" group is GONE — its three
 * categories (Config, Data, Project Files) are now first-class
 * language-level groups in the main list. Each keeps
 * its subcategory nesting; being single-category groups they list
 * their subcategories one level shallower (the flattening). */
export function exampleGroups(): ExampleGroup[] {
    const OTHER_ALL = [...OTHER_EXAMPLES, ...OTHER_PROJECT_EXAMPLES, ...OTHER_2_EXAMPLES];
    return [
        {label: "Python", categories: categorize(PY_EXAMPLES)},
        {label: "Markdown", categories: categorize([...MD_EXAMPLES, ...MD_2_EXAMPLES])},
        {label: "Text", categories: categorize([...TXT_EXAMPLES, ...TXT_2_EXAMPLES])},
        {label: "R", categories: categorize(R_EXAMPLES)},
        {label: "SQL", categories: categorize(SQL_EXAMPLES)},
        {label: "JSON", categories: categorize(JSON_EXAMPLES)},
        {label: "YAML", categories: categorize(YAML_EXAMPLES)},
        {label: "Shell", categories: categorize(SHELL_EXAMPLES)},
        // former "Other" categories promoted to top-level.
        {label: "Config", categories: categorize(OTHER_ALL.filter((e) => e.category === "Config"))},
        {label: "Data", categories: categorize(OTHER_ALL.filter((e) => e.category === "Data"))},
        {label: "Project Files", categories: categorize(OTHER_ALL.filter((e) => e.category === "Project files"))},
        // MATLAB — a single category, so the menu lists its
        // subcategories (Basics / Statistics / Plotting / Linear algebra /
        // Signals & control) one level shallower, exactly like R and Shell.
        {label: "MATLAB", categories: categorize(MATLAB_EXAMPLES)},
        // the Web family — Web Design (HTML/CSS) and Web
        // Development (JS/TS) as two categories under one group.
        {label: "Web", categories: categorize([...WEB_DESIGN_EXAMPLES, ...WEB_DEV_EXAMPLES])},
        // the remaining registry languages — each a single-
        // category group, so the menu lists its subcategories directly
        // (the R / Shell / MATLAB flattening).
        {label: "Java", categories: categorize([...JAVA_EXAMPLES, ...JAVA_2_EXAMPLES])},
        {label: "C", categories: categorize([...C_EXAMPLES, ...C_2_EXAMPLES])},
        {label: "C++", categories: categorize([...CPP_EXAMPLES, ...CPP_2_EXAMPLES])},
        {label: "Ruby", categories: categorize([...RUBY_EXAMPLES, ...RUBY_2_EXAMPLES])},
        {label: "PHP", categories: categorize([...PHP_EXAMPLES, ...PHP_2_EXAMPLES])},
        {label: "Go", categories: categorize([...GO_EXAMPLES, ...GO_2_EXAMPLES])},
        {label: "Lua", categories: categorize([...LUA_EXAMPLES, ...LUA_2_EXAMPLES])},
        {label: "Perl", categories: categorize([...PERL_EXAMPLES, ...PERL_2_EXAMPLES])},
        {label: "Rust", categories: categorize([...RUST_EXAMPLES, ...RUST_2_EXAMPLES])},
        {label: "Julia", categories: categorize([...JULIA_EXAMPLES, ...JULIA_2_EXAMPLES])},
        {label: "Kotlin", categories: categorize([...KOTLIN_EXAMPLES, ...KOTLIN_2_EXAMPLES])},
        {label: "Swift", categories: categorize([...SWIFT_EXAMPLES, ...SWIFT_2_EXAMPLES])},
        // the Windows-native scripting pair — single-category
        // groups, so the menu lists their subcategories directly.
        {label: "PowerShell", categories: categorize(POWERSHELL_EXAMPLES)},
        {label: "Batch", categories: categorize(BATCH_EXAMPLES)},
    ];
}
